/* ═══════════ BUNDLES ═══════════
   Each bundle owns a prefix, a theme class and four photographs named
   <prefix>1 … <prefix>4. To reshoot a bundle, drop new files over those
   names in img/ — nothing here needs touching.

     protein            p1 … p4        green   (#D7EBC2 / hero #D0E9C0)
     perfect portions   pp1 … pp4      #EFE9F0
     back to better     bb1 … bb4      #FFC273
     postpartum         postp1 … 4     #F8E8B7
     summer balance     sb1, sb2       #FFE473   (shown as an alternative)
     spring cleanse     sc1, sc2                 (shown as an alternative)

   Where each one is used on the results page:
     1–3  the fanned hero        1–4  both marquees, looped

   The dishes in "What's in your box" are shared across every bundle for now,
   named meal1 … meal8. Give a bundle its own menu by swapping MEAL_KEY below
   for that bundle's key. */
const MEAL_KEY='meal';
const MEAL_COUNT=6;        /* meal1 … meal6; the grid repeats from the top after that */
const BUNDLE={
 'Maximize my protein intake':      {key:'p',     theme:''},
 'Eat lighter to lose weight':      {key:'pp',    theme:'t-portions'},
 'Eat well after having a baby':    {key:'postp', theme:'t-postpartum'},
 'Eat well without overthinking it':{key:'bb',    theme:'t-better'}
};
const DEFAULT_GOAL='Maximize my protein intake';
/* Every image URL carries the moment the page loaded. Dropping a new file over
   an old name leaves the URL identical, and over file:// the browser never
   revalidates — it just keeps serving the copy it already has, so a swapped
   photograph looks like it did nothing. The stamp changes on every reload, so
   a replaced file always shows up. Pin it to a fixed string to cache normally. */
const BUST=`?v=${Date.now()}`;
/* img('p',3) -> 'img/p3.jpg' */
const img=(key,n)=>`img/${key}${n}.jpg${BUST}`;
/* the pictures that belong to one place on the page rather than to the pool,
   kept as PNGs: named('p','why') -> 'img/p-why.png' */
const named=(key,name)=>`img/${key}-${name}.png${BUST}`;
/* Variant A's hero carousel has photographs of its own — va-<prefix>1 … 6,
   as WebP — rather than the lifestyle pool the marquee and the content section
   draw on. The two sets are different pictures, so they get different names. */
const HERO_COUNT={p:6,bb:7,postp:9,pp:9};
const heroSet=key=>Array.from({length:HERO_COUNT[key]||6},
  (_,i)=>`img/va-${key}${i+1}.webp${BUST}`);
const imgSet=(key,from,to)=>
  Array.from({length:to-from+1},(_,i)=>img(key,from+i));
/* the marquees run <prefix>1 … 4 on a loop, on every bundle */
const MARQUEE_COUNT=4;


/* ═══════════ QUESTIONS ═══════════ */
const Q=[
 {id:'goal',type:'single',q:'What\u2019s your main priority right now?',sub:'',
  o:[['\uD83E\uDDD8','Maximize my protein intake'],['\uD83E\uDD55','Eat lighter to lose weight'],
     ['\uD83C\uDF7C','Eat well after having a baby'],['\uD83C\uDFDD\uFE0F','Eat well without overthinking it']]},
 {id:'sat',type:'slider',q:'How satisfied are you with how you eat today?',sub:''},
 {id:'challenges',type:'multi',q:'What are your challenges when it comes to eating?',sub:'Pick as many as you like',
  o:[['\u23F1\uFE0F','Finding time to cook'],['\uD83E\uDD14','Deciding what to eat'],
     ['\u2696\uFE0F','Eating a balanced diet'],['\uD83D\uDDD1\uFE0F','Wasting food'],
     ['\uD83C\uDF73','Cooking isn\u2019t my thing'],['\uD83D\uDCB6','Eating well on a budget']]},
 {id:'week',type:'multi',q:'Which best describes your week?',sub:'Pick as many as you like',
  o:[['\uD83D\uDCBC','Busy with work'],['\uD83C\uDFC3','Sport multiple times a week'],
     ['\uD83E\uDD42','Going out with friends'],['\uD83D\uDCDA','Studying'],
     ['\uD83C\uDFE0','Spend time at home mostly'],['\uD83C\uDFB2','A bit of everything']]},
 {id:'household',type:'single',q:'How many people will eat Every with you?',sub:'',
  o:[['\uD83D\uDC64','Just me'],['\uD83D\uDC65','Me & my partner'],
     ['\uD83D\uDC68\u200D\uD83D\uDC69\u200D\uD83D\uDC67','Family with kids'],['\uD83C\uDFE0','Me & roommates']]},
 {id:'eater',type:'single',q:'What type of eater are you?',sub:'',
  o:[['\uD83C\uDF0D','I love trying new tastes'],['\u2B50','I like sticking to my favorites'],
     ['\uD83D\uDD00','A mix of staples and new things'],['\u26A1','I keep it simple, quick and easy']]},
 {id:'watch',type:'multi',q:'Anything you watch for in food?',sub:'Pick as many as you like',
  o:[['\uD83D\uDCAA','Getting more protein'],['\uD83C\uDF3E','Eating more fibre'],
     ['\uD83C\uDF43','Keeping portions in check'],['\uD83D\uDEAB','Lowering my sugar intake'],
     ['\uD83C\uDF31','Eating more vegan'],['\u2014','Nothing specific right now']]}
];

/* One entry per point on the slider, in order, so every one of the five has a
   label and a line of its own and moving the knob always says something new.
   The three drawings are shared across them by artOf below. */
const SAT=[
 {f:'😞',l:'Not satisfied'},
 {f:'😕',l:'Could be better'},
 {f:'😐',l:'Somewhat satisfied'},
 {f:'🙂',l:'Mostly satisfied'},
 {f:'😄',l:'Very satisfied'}];
const zoneOf=v=>SAT[Math.max(0,Math.min(SAT.length-1,v-1))];
